  /** GradientTintedIconButton.kt:65-77 modifierColor colours */
  private tintColors(): string[] {
    return this.pressed ? [this.theme.colors.textSecondary, this.theme.colors.textSecondary] : this.activeColors();
  }

  private iconTint(): ResourceColor {
    return this.contentColor === '' ? this.theme.colors.textSecondary : this.contentColor;
  }

  private innerSize(): number {
    return ICON_SIZE - 2 * BORDER_WIDTH;
  }

  @Builder
  iconContent(): void {
    Stack({ alignContent: Alignment.Center }) {
      // GradientTintedIconButton.kt:59 pressed background: offsetGradientBackground(colors, 200f, 0f), circle-clipped
      if (this.pressed) {
        Stack({ alignContent: Alignment.TopStart }) {
          OffsetGradientLayerComponent({
            colors: this.activeColors(),
            widthPx: PRESSED_GRADIENT_WIDTH_PX,
            offsetPx: PRESSED_GRADIENT_OFFSET_PX,
            tilesEachSide: PRESSED_GRADIENT_TILES
          })
        }
